--- 角色详情界面设置节点信息
---@param roleData RoleView
function BattleRoleInfoNode:SetRoleInfoCharacterInfoDialog(roleView)
    self:AnimationDefault()
    self.roleId = roleView.id
    local buffHeadPath = UIBattlingTools.GetCharacterSelectSignHeadPath(BattleInfo.myCamp, self.roleId)
    self.ImgRoleIcon:LoadSprite(buffHeadPath)
    -- 血量
    local attr = roleView.attr
    local curHp = attr:GetValue(Constants.AttrTypeId.NowHp) -- 当前血量
    local curHpMax = attr:GetValue(Constants.AttrTypeId.Hp) -- 当前血量上限
    local hpMax = UIBattlingDataMgr:GetCharactorHpMaxValueByBattleFieldId(self.roleId)  -- 初始血量上限
    self:SetRoleHPValue(curHp / hpMax)
    KTool.SetActive(self.TF_groupLock.gameObject, hpMax ~= curHpMax)
    self:SetHpBlockSliderValue((hpMax - curHpMax) / hpMax)
    -- 护盾
    local shield = UIBattlingCtrlMgr:GetInstance():GetCharacterShieldValue(self.roleId)
    self:SetShieldSliderValue(shield[1] / shield[2])
    -- SP
    local spMax = checkInt(roleView.roleData.maxSP)
    -- local curSp = roleView.roleData.currentEnergy 
    local curSp, spInRoundStart = UIBattlingCtrlMgr:GetInstance():GetBattlingInfoDialog():GetCharacterSpInfo(self.roleId)
    if not IsNull(self.EnergyDotGroup) and not IsNull(self.ImgDot) then
        for i = 1, spMax do
            local spNode = KTool.Instantiate(self.EnergyDotGroup.gameObject, self.ImgDot.gameObject)
            KTool.SetActive(spNode,true)
            local Img1 = spNode.transform:Find("Img1")
            KTool.SetActive(Img1.gameObject, true)
            local switchImg1 = KTool.GetComponent(Img1.gameObject, typeof(UISwitchImage))
            switchImg1.Status = i <= curSp and LIST_SP_ANIMATION.Bright or LIST_SP_ANIMATION.Dark
        end
    end
    -- 切换血条颜色
    local isPlayer = checkBool(roleView.isPlayer)
    self:SetRoleHPShowStatus(isPlayer)
    -- 元素和职业
    self:SetRoleElementTypeIcon()
    xTry(function()
        if isPlayer then
            -- local path = UIBattlingTools.GetCareerIconCommon(roleView.roleData.career, true)
            -- print("职业图标 ", path)
            -- self.ImgType:LoadSprite(path)

            local roleDataUI = UIBattlingDataMgr:GetCharactorDataById(self.roleId)
            local cardId = roleDataUI.cardId -- 角色卡牌Id
            local cardVo = CardConfMgr:GetCardByRefId(cardId)
            self.ImgType:LoadSprite(UIBattlingTools.GetCareerIconCommon(cardVo.career, true))
        end
    end)
    KTool.SetActive(self.ImgType.gameObject, isPlayer)
end

