function BattleRoleInfoNode:SetRoleInfo(roleData)
    self:AnimationDefault()
    ---Data
    self.roleId = roleData.battleFieldId
    self.element = roleData.AttrType
    self.roleType = roleData.roleType
    self.roleAlive = true
    self.hpMaxNow = 1 -- 初始化人物血量上限
    self.numMaxSP = roleData.SpMax
    UIBattlingCtrlMgr:GetInstance():AddRootOurTeamBuff(self.roleId, self.CharactorBuffRoot)
    --- 设置角色 血量上限
    local roleHpMax = UIBattlingDataMgr:GetCharactorHpMaxValueByBattleFieldId(self.roleId)
    self.hpMax = roleHpMax
    ---Component
    local buffHeadPath = UIBattlingTools.GetCharacterSelectSignHeadPath(BattleInfo.myCamp, self.roleId)
    self.ImgRoleIcon:LoadSprite(buffHeadPath)
    self:SetRoleElementTypeIcon()
    local hpStart = checkNumber(roleData.HpPreInBattleStart)
    self:SetRoleHPValue(hpStart)
    self:SetShieldSliderValue(0)
    
    self.listSPNodes = {}
    if not IsNull(self.EnergyDotGroup) and not IsNull(self.ImgDot) then
        for i = 1, self.numMaxSP do
            local spNode = KTool.Instantiate(self.EnergyDotGroup.gameObject, self.ImgDot.gameObject)
            KTool.SetActive(spNode,true)
            local switchImg1
            local Img1 = spNode.transform:Find("Img1")
            if not IsNull(Img1) then
                switchImg1 = KTool.GetComponent(Img1.gameObject, typeof(UISwitchImage)) 
            end
            local goImg2 = spNode.transform:Find("Img2")
            local tableSPNode = { Img1 = switchImg1, Img2 = goImg2, }
            table.insert(self.listSPNodes, tableSPNode)
        end
    end
    
    local roleViewData = BattleViewMgr:FindRoleView(self.roleId)
    local isPlayer = checkBool(roleViewData.isPlayer)
    
   
    xTry(function()
        if isPlayer then
            local roleDataUI = UIBattlingDataMgr:GetCharactorDataById(self.roleId)
            local cardId = roleDataUI.cardId -- 角色卡牌Id
            local cardVo = CardConfMgr:GetCardByRefId(cardId)
            self.ImgType:LoadSprite(UIBattlingTools.GetCareerIconCommon(cardVo.career, true))
        end
        self:SetRoleHPShowStatus(isPlayer)
    end)
    
    KTool.SetActive(self.ImgType.gameObject, isPlayer)
    
    self:SetEventShowRoleInfo()
end

