function BattleRoleInfoNode:SetRoleHPValue(hpStart)
    hpStart = checkNumber(hpStart)
    self:SetHpTopSliderValue(hpStart)
    self:SetHpMidSliderValue(hpStart)
end

function BattleRoleInfoNode:SetRoleHPWithAnimation(preNow)
    xTry(function()
        local hpEx = self.hpTopPer
        local hpNow = preNow -- 人物血量 变化后（百分比）
        self:SetHpTopSliderValue(preNow)
        if hpNow < hpEx then
            if self.coShowHpChange then
                if self.timeProcess <= Constants.TIME_HP_CHANGE then
                    self.timeProcess = 0
                    self.hpPreChange = self.hpMidPer - hpNow
                else
                    cs_coroutine.stop(self.coShowHpChange)
                    self.coShowHpChange = nil
                end
            end
            if IsNull(self.coShowHpChange) then
                --- 血量减少
                self.coShowHpChange = cs_coroutine.start(function()
                    self.hpPreChange = self.hpMidPer - hpNow
                    self.timeProcess = 0
                    while self.timeProcess <= Constants.TIME_HP_CHANGE do
                        self.timeProcess = self.timeProcess + Time.deltaTime
                        local hpChangePre = Time.deltaTime / Constants.TIME_HP_CHANGE
                        self:SetHpMidSliderValue(self.hpMidPer - hpChangePre * self.hpPreChange)
                        cs_coroutine.yield_return()
                    end
                    self.timeProcess = 999 -- 预防多段的保险值
                    self.coShowHpChange = nil
                end)
            end
        else
            -- 加血的话，不用插值，直接加上去
            self:SetHpMidSliderValue(preNow)
        end
    end)
end

function BattleRoleInfoNode:SetRoleShield(value, valueMax)
    if isNull(self.shieldValueEX) then 
        self.shieldValueEX = 0 
    end
    if valueMax == 0 then
        valueMax = 0.1
    end
    local shieldPre = value / valueMax
    shieldPre = math.floor(shieldPre * 100 + 0.5) * 0.01
    if shieldPre <= 0 then
        shieldPre = 0
    elseif shieldPre >= 1 then
        shieldPre = 1
    end
    KTool.SetActive(self.Slider1.gameObject, shieldPre > 0)
    if shieldPre <= 0 then return shieldPre end
    self:SetShieldSliderValue(shieldPre)
    self.shieldValueEX = shieldPre
end

