function BattleRoleInfoNode:AddValueOfRoleSPPoint(numPoint)
    if IsNull(numPoint) then return false end
    if self.curRoleHaveSPPoint >= self.numMaxSP then return false end
    local spPointNow = self.curRoleHaveSPPoint + numPoint
    if spPointNow >= self.numMaxSP then
        return true, self.numMaxSP - self.curRoleHaveSPPoint
    else
        return true, numPoint
    end
end

function BattleRoleInfoNode:UpdateRoleSPPoint(numPoint)
    local spValue = self.curRoleHaveSPPoint + numPoint
    self:SetSpValue(spValue, TYPE_SP.SpTemp)
end

function BattleRoleInfoNode:SetRoleSP(SPValue)
    self:SetSpValue(SPValue, TYPE_SP.SpPoint)
    self.curRoleHadSPRoundStart = SPValue
end

function BattleRoleInfoNode:SetSpValue(numPoint, spType)
    self.curRoleHaveSPPoint = numPoint
    if spType == TYPE_SP.SpPoint then
        self:SetSPNode()
    else
       self:SetTempSPNode()
    end
end

function BattleRoleInfoNode:SetSPNode()
    local pointHad = checkNumber(self.curRoleHadSPRoundStart)
    local pointNow = checkNumber(self.curRoleHaveSPPoint)
    local vDifference = pointNow - pointHad
    local numMaxSP = checkNumber(self.numMaxSP)
    if vDifference == 0 then return end
    if vDifference > 0 then
        self:SetSPNodeAnimatorCommon(pointHad, pointNow)
        if pointNow >= numMaxSP then
            self:CleanCoShowSPNodeActivation()
            self.coShowSPNodeActivation = cs_coroutine.start(function()
                cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.6))
                self:SetSPNodeAnimatorActivation()
            end)
        end
    else
        self:SetSPNodeAnimatorCommon(pointHad, pointNow)
    end
end

function BattleRoleInfoNode:SetSPNodeAnimatorCommon(pointHad, pointNow)
    for i = 1, #self.listSPNodes do
        local tableSPNode = self.listSPNodes[i]
        local switchImg1 = tableSPNode.Img1
        KTool.SetActive(switchImg1.gameObject, true)
        local goImg2 = tableSPNode.Img2
        KTool.SetActive(goImg2, false)
        local status = i <= pointNow and LIST_SP_ANIMATION.Bright or LIST_SP_ANIMATION.Dark
        switchImg1.Status = status
        if i > pointHad and i <= pointNow then
            UIBattlingTools.ReloadPTCOfBattling(Constants.UIBattlingObjPoolPTC.PTC_SP_DOT, switchImg1.gameObject, 1)
        end
    end
end

function BattleRoleInfoNode:SetSPNodeAnimatorActivation()
    if isNull(self.listSPNodes) then return end
    for i, node in ipairs(self.listSPNodes) do
        local switchImg1 = node.Img1
        local goImg2 = node.Img2
        KTool.SetActive(switchImg1.gameObject, false)
        KTool.SetActive(goImg2.gameObject, true)
    end
end

function BattleRoleInfoNode:CleanCoShowSPNodeActivation()
    if self.coShowSPNodeActivation then
        cs_coroutine.stop(self.coShowSPNodeActivation)
        self.coShowSPNodeActivation = nil
    end
end

function BattleRoleInfoNode:SetTempSPNode()
    for i = 1, #self.listSPNodes do
        local tableSPNode = self.listSPNodes[i]
        local switchImg1 = tableSPNode.Img1
        KTool.SetActive(switchImg1.gameObject, true)
        local goImg2 = tableSPNode.Img2
        KTool.SetActive(goImg2, false)
        local status
        if i <= self.curRoleHadSPRoundStart then
            status = LIST_SP_ANIMATION.Bright
        elseif i > self.curRoleHadSPRoundStart and i <= self.curRoleHaveSPPoint then
            status = LIST_SP_ANIMATION.Bright
        else
            status = LIST_SP_ANIMATION.Dark
        end
        switchImg1.Status = status
    end
end

function BattleRoleInfoNode:ConversionTempSP()
    self:ResetRoleSP()
    --self:SetSpValue(self.curRoleHaveSPPoint ,TYPE_SP.SpPoint)
end

function BattleRoleInfoNode:ResetRoleSP()
    self:SetEventShowRoleInfo()
    if self.curRoleHadSPRoundStart ~= self.curRoleHaveSPPoint then
        self.curRoleHaveSPPoint = self.curRoleHadSPRoundStart
        for i = 1, #self.listSPNodes do
            local status = i <= self.curRoleHaveSPPoint and LIST_SP_ANIMATION.Bright or LIST_SP_ANIMATION.Dark
            local tableSPNode = self.listSPNodes[i]
            local switchImg1 = tableSPNode.Img1
            KTool.SetActive(switchImg1.gameObject, true)
            local goImg2 = tableSPNode.Img2
            KTool.SetActive(goImg2, false)
            switchImg1.Status = status
        end
    end
end

function BattleRoleInfoNode:SetEventShowRoleInfo()
    self.uiEventProxy.onPointerClick = function()
        if not checkBool(self.roleAlive) then return end
        local isAutoBattle = UIBattleSettingMgr.isAutoBattle
        if isAutoBattle then return end
        local guideIsRunning = GamePlayGuideMgr and GamePlayGuideMgr.guideIsRunning
        if guideIsRunning then return end
        if not checkBool(UIBattlingCtrlMgr:GetInstance():GetBooleanPlayerInput()) then return end
        UIBattlingCtrlMgr:GetInstance():SetBooleanOpenDetection(false)
        UIBattlingCtrlMgr:GetInstance():GetBattlingDialog():SetBattleUIState(false)
        local roleCampType = UIBattlingDataMgr:GetRoleCampByRoleId(self.roleId)
        UIBattlingCtrlMgr:GetInstance():GetBattlingInfoDialogCanvasGroup().alpha = 0
        UIModule.OpenDialog({ id = Constants.UITypeIds.UIBattlingCharactorInfoDialog, parameters = { id = self.roleId, camp = roleCampType, callBack = Bind(self, self.CloseCharacterInfoCallBack) } })
    end
end

function BattleRoleInfoNode:SetEventBuffSkill(cbChoice, cbRefresh, skillCard)
    if not checkBool(self.roleAlive) then return end
    self:AnimationDefault()
    self.uiEventProxy.onPointerClick = function()
        if cbChoice then cbChoice(self.roleId) end
        if cbRefresh then cbRefresh() end
        self:AnimationSkillChoose()
        Events.Broadcast(Constants.EventNames.UIBattleBuffSkillDone)
    end
end

function BattleRoleInfoNode:SetHpTopSliderValue(value)
    self.hpTopPer = value
    local remapValue = UIBattlingTools.Remap(value, 0, 1, 0, 0.85)
    self.IMG_hpTopSlider.fillAmount = remapValue

    -- 根据血线修改血条颜色
    if value > 0.7 then
        self.IMG_hpTopSlider.color = XLuaUtils.HexToColor(Constants.HPSliderColor.Green)
    elseif value > 0.4 then
        self.IMG_hpTopSlider.color = XLuaUtils.HexToColor(Constants.HPSliderColor.Yellow)
    else
        self.IMG_hpTopSlider.color = XLuaUtils.HexToColor(Constants.HPSliderColor.Red)
    end
end

function BattleRoleInfoNode:SetHpMidSliderValue(value)
