function BattleRoleInfoNode:SetHpEndPoint(value)
    -- UI说血条的小飞棍不要跟着走 不能理解
    -- local remapValue = UIBattlingTools.Remap(value, 0, 1, 179, 31)
    -- self.TF_hpEndPoint.localRotation = Quaternion.Euler(0,0,remapValue)
end

function BattleRoleInfoNode:SetShieldEndPoint(value)
    local remapValue = UIBattlingTools.Remap(value, 0, 1, 179, 31)
    self.TF_shieldEndPoint.localRotation = Quaternion.Euler(0,0,remapValue)
end

--- 从另一个battleRoleInfoNode拷贝数据过来
--- （现在是给角色详情页面使用，打开角色详情的时候从UIBattlingDialog拷贝数据过来）
---@param other BattleRoleInfoNode
function BattleRoleInfoNode:CopyInfoFrom(other)
    self:SetRoleElementTypeIcon()
    self:SetRoleHPShowStatus(other.isPlayer)
    self:SetHpTopSliderValue(other.hpTopPer)
    self:SetHpMidSliderValue(other.hpMidPer)
    self:SetHpBlockSliderValue(other.hpBlockPer)
    self:SetShieldSliderValue(other.shieldPer)
    self:SetRoleSP(other.curRoleHadSPRoundStart)
end

function BattleRoleInfoNode:RootAnimatorPlay(name)
    if not isNull(self.RootAnimator) then
        self.RootAnimator:Play(name,0, 0)
        self.RootAnimator:Update(0)
    end
end

function BattleRoleInfoNode:EnterBattlingPerformance()
    -- self.CanvasGroup_root:DOFade(0.5, 0.25)
    self.TF_root:DOScale(1, 0.25)
end

function BattleRoleInfoNode:ExitBattlingPerformance()
    -- self.CanvasGroup_root:DOFade(1, 0.25)
    self.TF_root:DOScale(1, 0.25)
end

function BattleRoleInfoNode:BattlingPerformanceSelectRole()
    -- self:RootAnimatorPlay(LIST_ROOT_ANIMATION.BattlingChoose)
    -- self.CanvasGroup_root:DOFade(1, 0.25)
    self.TF_root:DOScale(1.18, 0.25)
end

function BattleRoleInfoNode:BattlingPerformanceCancleRole()
    -- self:RootAnimatorPlay(LIST_ROOT_ANIMATION.BattlingNormal)
    -- self.CanvasGroup_root:DOFade(0.5, 0.25)
    self.TF_root:DOScale(1, 0.25)
end

function BattleRoleInfoNode:SelectRoleInfo()
    -- self:RootAnimatorPlay(LIST_ROOT_ANIMATION.DetailChoose)
    self.TF_root:DOScale(1.1, 0.25)
end

function BattleRoleInfoNode:CancelRoleInfo()
    -- self:RootAnimatorPlay(LIST_ROOT_ANIMATION.DetailCancel)
    self.TF_root:DOScale(1, 0.25)
end

function BattleRoleInfoNode:AnimationSkillChoose()
    self:RootAnimatorPlay(LIST_ROOT_ANIMATION.SkillChoose)
end

function BattleRoleInfoNode:AnimationDefault()
    -- self:RootAnimatorPlay(LIST_ROOT_ANIMATION.Default)
    KTool.SetActive(self.ExitGroup.gameObject, false)
    KTool.SetActive(self.FXRoot.gameObject, false)
    self.TF_root.localScale = Vector3.one
end

function BattleRoleInfoNode:AnimationExit()
    self:RootAnimatorPlay(LIST_ROOT_ANIMATION.Exit)
end

return BattleRoleInfoNode




